def repartir_imputaciones_existentes(apps, schema_editor):
    """Los adelantos van a ordinarias; el capital ya imputado se reparte como si se hubiera pagado con esta regla."""
    ImputacionPago = apps.get_model('gastos', 'ImputacionPago')
    ImputacionPago.objects.filter(concepto='adelanto', parte='').update(parte='ordinario')
    pagado = {}
    for imp in ImputacionPago.objects.filter(concepto__in=['capital', 'adelanto']).select_related(
            'detalle_liquidacion').order_by('pk'):
        detalle = imp.detalle_liquidacion
        if detalle is None:
            continue
        montos = montos_del_cupon(detalle.monto_total, detalle.monto_extraordinario,
                                  detalle.monto_fondo_reserva, detalle.monto_convenio)
        ya_pagado = pagado.setdefault(detalle.pk, dict.fromkeys(montos, Decimal('0')))
        if imp.concepto == 'adelanto':
            ya_pagado['ordinario'] += imp.monto
            continue
        pendiente = {parte: max(montos[parte] - ya_pagado[parte], Decimal('0')) for parte in montos}
        partes = dict(repartir_capital(pendiente, imp.monto))
        # Si ya estaba pagado de más (datos viejos), la diferencia queda en ordinarias.
        partes['ordinario'] = partes.get('ordinario', Decimal('0')) + imp.monto - sum(partes.values(), Decimal('0'))
        partes = [(parte, monto) for parte, monto in partes.items() if monto > 0]
        imp.parte, imp.monto = partes[0]
        imp.save(update_fields=['parte', 'monto'])
        for parte, monto in partes[1:]:
            ImputacionPago.objects.create(pago_id=imp.pago_id, detalle_liquidacion=detalle,
                                          concepto='capital', parte=parte, monto=monto)
        for parte, monto in partes:
            ya_pagado[parte] += monto




